import itertools,json
jobs="ABCDE"
sc={"A":[10,7,11,4,4],"B":[3,1,1,4,8],"C":[5,4,5,6,2],"D":[3,3,7,1,11],"E":[10,9,10,1,9]}
tr=dict(zip(jobs,[[0,3,3,5,0],[5,0,3,2,0],[5,3,0,2,1],[4,2,4,0,5],[1,5,4,1,0]]))
def nominal(p):
    return sum(sc[j][i] for i,j in enumerate(p))+sum(tr[a][jobs.index(b)] for a,b in zip(p,p[1:]))
def legal(p,s):
    if p.index("A")>p.index("D"): return False
    if s=="rain": return p[4]!="C" and p[0]!="A"
    if s=="road": return p[0]!="B" and p[1]!="C"
    return p[4] not in "DB"
def penalty(p,s):
    if s=="rain": return 8*max(0,p.index("E"))
    if s=="road": return 5*max(0,p.index("D")+1-3)
    return 5*max(0,p.index("E")+1-2)
results=[]
for p in itertools.permutations(jobs):
    if p.index("A")>p.index("D"): continue
    near=[(p,0)]
    for i in range(5):
        for j in range(i+1,5):
            q=list(p);q[i],q[j]=q[j],q[i]
            near.append((tuple(q),1))
    repairs={}; costs={}
    for s in ["rain","road","lift"]:
        options=[(nominal(q)+penalty(q,s)+x,"".join(q)) for q,x in near if legal(q,s)]
        if not options: break
        costs[s],repairs[s]=min(options)
    else:
        results.append((nominal(p)+max(costs.values()),"".join(p),repairs,costs,nominal(p)))
results.sort()
best=results[0]
out=dict(roster=best[1],score=best[0],repairs=best[2],repair_costs=best[3],feasible_count=len(results),next_score=min(r[0] for r in results if r[0]>best[0]))
print(json.dumps(out))
print("published nominal",best[4], "optima",sum(r[0]==best[0] for r in results))

