import itertools,json
J="ABCDE"; published="EABDC"
S={"A":[10,7,11,4,4],"B":[3,1,1,4,8],"C":[5,4,5,6,2],"D":[3,3,7,1,11],"E":[10,9,10,1,9]}
T=dict(zip(J,[[0,3,3,5,0],[5,0,3,2,0],[5,3,0,2,1],[4,2,4,0,5],[1,5,4,1,0]]))
def distance(q):
    perm=[published.index(x) for x in q]
    seen=set(); cycles=0
    for i in range(5):
        if i not in seen:
            cycles+=1
            while i not in seen:
                seen.add(i); i=perm[i]
    return 5-cycles
groups={i:[] for i in range(3)}
for q in itertools.permutations(J):
    if q.index("A")>q.index("D") or q[4]=="C" or q[0] in "AE": continue
    k=distance(q)
    if k>2: continue
    nominal=sum(S[x][i] for i,x in enumerate(q))+sum(T[a][J.index(b)] for a,b in zip(q,q[1:]))
    cost=nominal+8*q.index("E")+k+(10 if k==2 else 0)
    groups[k].append((cost,"".join(q)))
best=min(v for g in groups.values() for v in g)
out={"roster":best[1],"score":best[0],"best_by_swaps":{str(k):min(g)[0] if g else None for k,g in groups.items()},"feasible_by_swaps":{str(k):len(g) for k,g in groups.items()}}
# Verify cycle distance independently via two breadth-first exchange layers.
dist={published:0}
front=[published]
for k in (1,2):
    nextfront=[]
    for p in front:
        for i in range(5):
            for j in range(i+1,5):
                q=list(p); q[i],q[j]=q[j],q[i]; q="".join(q)
                if q not in dist: dist[q]=k; nextfront.append(q)
    front=nextfront
for q,k in dist.items(): assert distance(q)==k
for k,g in groups.items():
    assert len(g)==sum(d==k and p.index("A")<p.index("D") and p[4]!="C" and p[0] not in "AE" for p,d in dist.items())
print(json.dumps(out))

